  // Test maximum valid length (200 characters)
  const maxValidTitle = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.alphabets(200), // Exactly 200 characters
        description: {
          type: "full",
          content: "Maximum valid title",
