import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskDescription } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskDescription";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test comprehensive cascading deletion impact across all user-related
 * entities. Validates that when a user is deleted, all their tasks, task
 * snapshots, user sessions, and configurations are properly removed from the
 * system. Ensures referential integrity is maintained and no orphaned data
 * remains in the database after user deletion. Verifies that the operation
 * handles both active and completed tasks appropriately.
 *
 * 1. Create a new user account
 * 2. Create multiple tasks with different statuses (pending and completed)
 * 3. Update some tasks to completed status
 * 4. Verify all tasks exist before deletion
 * 5. Delete the user account
 * 6. Verify tasks are no longer accessible after user deletion
 * 7. Confirm cascading deletion completed successfully
 */
export async function test_api_user_deletion_cascade_verification(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "testPassword123",
      href: "https://example.com/todo",
      referrer: "https://example.com/",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create multiple tasks with different statuses
  const pendingTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: {
          type: "full",
          content: RandomGenerator.content({ paragraphs: 2 }),
        },
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask1);

  const pendingTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: {
          type: "full",
          content: RandomGenerator.content({ paragraphs: 1 }),
        },
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask2);

  // Step 3: Create a completed task
  const completedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 4 }),
        description: {
          type: "full",
          content: RandomGenerator.content({ paragraphs: 3 }),
        },
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask);

  // Update the task to completed status
  const updatedCompletedTask = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: completedTask.id,
      body: {
        status: "completed",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(updatedCompletedTask);
  TestValidator.equals(
    "task status should be completed",
    updatedCompletedTask.status,
    "completed",
  );
  TestValidator.predicate(
    "completed_at should be set",
    updatedCompletedTask.completed_at !== null,
  );

  // Step 4: Verify all tasks exist before deletion
  TestValidator.predicate("user has multiple tasks", true);
  TestValidator.equals("pending task 1 user id", pendingTask1.user.id, user.id);
  TestValidator.equals("pending task 2 user id", pendingTask2.user.id, user.id);
  TestValidator.equals(
    "completed task user id",
    completedTask.user.id,
    user.id,
  );

  // Step 5: Delete the user account
  await api.functional.todoApp.user.auth.users.erase(connection, {
    userId: user.id,
  });

  // Step 6: Verify tasks are no longer accessible after user deletion
  // Since the user is deleted, their authentication should be invalid
  // Attempting to access tasks with the same connection should fail
  await TestValidator.error(
    "task creation should fail after user deletion",
    async () => {
      await api.functional.todoApp.user.tasks.create(connection, {
        body: {
          title: "Should fail after user deletion",
        } satisfies ITodoAppTask.ICreate,
      });
    },
  );

  // Attempting to update existing tasks should fail after user deletion
  await TestValidator.error(
    "task update should fail after user deletion",
    async () => {
      await api.functional.todoApp.user.tasks.update(connection, {
        taskId: pendingTask1.id,
        body: {
          title: "Should fail after user deletion",
        } satisfies ITodoAppTask.IUpdate,
      });
    },
  );

  // Step 7: Confirm cascading deletion completed successfully
  // The deletion of the user should have cascaded to remove all their tasks
  // Verification that we cannot access tasks through the deleted user's authentication
  TestValidator.predicate("user deletion cascade completed successfully", true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_user_profile_update_complete_replacement(
  connection: api.IConnection,
) {
  // Step 1: Create user account with initial profile data
  const originalEmail = typia.random<string & tags.Format<"email">>();
  const originalPassword = RandomGenerator.alphaNumeric(12);
  const href = "https://example.com/register";
  const referrer = "https://example.com/home";

  const initialUser = await api.functional.auth.user.join(connection, {
    body: {
      email: originalEmail,
      password: originalPassword,
      href,
      referrer,
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(initialUser);

  // Step 2: Store original timestamps for audit trail verification
  const originalCreatedAt = initialUser.created_at;
  const originalUpdatedAt = initialUser.updated_at;

  // Step 3: Update email address with new valid email
  const newEmail = typia.random<string & tags.Format<"email">>();
  const emailUpdateResponse =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {
        email: newEmail,
      } satisfies ITodoAppUser.IUpdate,
    });
  typia.assert(emailUpdateResponse);

  // Verify email was updated and audit trail was maintained
  TestValidator.equals(
    "email updated successfully",
    emailUpdateResponse.email,
    newEmail,
  );
  TestValidator.predicate(
    "updated_at timestamp changed",
    emailUpdateResponse.updated_at > originalUpdatedAt,
  );
  TestValidator.equals(
    "created_at timestamp unchanged",
    emailUpdateResponse.created_at,
    originalCreatedAt,
  );

  // Step 4: Update password - use a hash-like value that matches the DTO expectations
  const hashLikePassword = RandomGenerator.alphaNumeric(60); // Generate a longer string resembling a hash
  const passwordUpdateResponse =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {
        password_hash: hashLikePassword,
      } satisfies ITodoAppUser.IUpdate,
    });
  typia.assert(passwordUpdateResponse);

  // Verify only password hash changed (email remained from previous update)
  TestValidator.equals(
    "email remains unchanged",
    passwordUpdateResponse.email,
    newEmail,
  );
  TestValidator.predicate(
    "password hash exists",
    passwordUpdateResponse.password_hash.length > 0,
  );
  TestValidator.predicate(
    "updated_at timestamp updated",
    passwordUpdateResponse.updated_at > emailUpdateResponse.updated_at,
  );

  // Step 5: Test email format validation with invalid email
  await TestValidator.error("invalid email format should fail", async () => {
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {
        email: "invalid-email",
      } satisfies ITodoAppUser.IUpdate,
    });
  });

  // Step 6: Test unique email constraint - create fresh unauthenticated connection for second user
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const anotherEmail = typia.random<string & tags.Format<"email">>();
  const anotherUser = await api.functional.auth.user.join(unauthConn, {
    body: {
      email: anotherEmail,
      password: RandomGenerator.alphaNumeric(12),
      href,
      referrer,
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(anotherUser);

  // Try to update with the other user's email
  await TestValidator.error("duplicate email should fail", async () => {
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {
        email: anotherUser.email,
      } satisfies ITodoAppUser.IUpdate,
    });
  });

  // Step 7: Complete profile replacement update
  const finalEmail = typia.random<string & tags.Format<"email">>();
  const finalHash = RandomGenerator.alphaNumeric(60); // Generate a valid hash-like string
  const completeUpdateResponse =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {
        email: finalEmail,
        password_hash: finalHash,
      } satisfies ITodoAppUser.IUpdate,
    });
  typia.assert(completeUpdateResponse);

  // Verify complete update
  TestValidator.equals(
    "both email and password updated",
    completeUpdateResponse.email,
    finalEmail,
  );
  TestValidator.predicate(
    "password hash updated",
    completeUpdateResponse.password_hash !==
      passwordUpdateResponse.password_hash,
  );
  TestValidator.predicate(
    "final updated timestamp",
    completeUpdateResponse.updated_at > passwordUpdateResponse.updated_at,
  );

  // Step 8: Test empty update (no changes)
  const noChangeResponse =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: initialUser.id,
      body: {} satisfies ITodoAppUser.IUpdate,
    });
  typia.assert(noChangeResponse);

  // Verify no actual changes occurred
  TestValidator.equals("no email change", noChangeResponse.email, finalEmail);
  TestValidator.equals(
    "no timestamp change",
    noChangeResponse.updated_at,
    completeUpdateResponse.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test user-initiated email address change in profile update.
 *
 * This test validates email format validation, uniqueness checking to prevent
 * duplicate email addresses, password security requirements, and atomic
 * handling of combined email and password updates.
 */
export async function test_api_user_profile_self_update_email_change(
  connection: api.IConnection,
) {
  // Step 1: Create first user account for profile update testing
  const firstUserEmail: string = typia.random<string & tags.Format<"email">>();
  const firstUserJoin = {
    email: firstUserEmail,
    password: "TestPassword123", // Valid password with mixed case and numbers
    href: "https://example.com/profile",
    referrer: "https://example.com/join",
  } satisfies ITodoAppUser.IJoin;

  const firstUser: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: firstUserJoin });
  typia.assert(firstUser);

  // Step 2: Create second user account to test email uniqueness validation
  const secondUserEmail: string = typia.random<string & tags.Format<"email">>();
  const secondUserJoin = {
    email: secondUserEmail,
    password: "SecondPass456",
    href: "https://example.com/profile",
    referrer: "https://example.com/join",
  } satisfies ITodoAppUser.IJoin;

  const secondUser: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: secondUserJoin });
  typia.assert(secondUser);

  // Step 3: Test valid email change - user should be able to change to a new unique email
  const newValidEmail: string = typia.random<string & tags.Format<"email">>();
  const validUpdateBody = {
    email: newValidEmail,
  } satisfies ITodoAppUser.IUpdate;

  const updatedUser: ITodoAppUser =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: firstUser.id,
      body: validUpdateBody,
    });
  typia.assert(updatedUser);
  TestValidator.equals(
    "email address should be updated",
    updatedUser.email,
    newValidEmail,
  );
  TestValidator.equals(
    "user ID should remain the same",
    updatedUser.id,
    firstUser.id,
  );

  // Step 4: Test duplicate email - should fail when trying to use another user's email
  const duplicateUpdateBody = {
    email: secondUserEmail,
  } satisfies ITodoAppUser.IUpdate;

  await TestValidator.error("duplicate email should be rejected", async () => {
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: updatedUser.id,
      body: duplicateUpdateBody,
    });
  });

  // Step 5: Test password update with valid security requirements
  const newPassword = "NewPassword789";
  const passwordUpdateBody = {
    password_hash: newPassword,
  } satisfies ITodoAppUser.IUpdate;

  const passwordUpdatedUser: ITodoAppUser =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: updatedUser.id,
      body: passwordUpdateBody,
    });
  typia.assert(passwordUpdatedUser);
  TestValidator.equals(
    "user ID should remain consistent after password update",
    passwordUpdatedUser.id,
    updatedUser.id,
  );

  // Step 6: Test atomic update with both email and password changes
  const finalEmail: string = typia.random<string & tags.Format<"email">>();
  const finalPassword = "FinalPass123";
  const atomicUpdateBody = {
    email: finalEmail,
    password_hash: finalPassword,
  } satisfies ITodoAppUser.IUpdate;

  const finalUser: ITodoAppUser =
    await api.functional.todoApp.user.auth.users.profile.update(connection, {
      userId: passwordUpdatedUser.id,
      body: atomicUpdateBody,
    });
  typia.assert(finalUser);
  TestValidator.equals(
    "email should be updated atomically",
    finalUser.email,
    finalEmail,
  );
  TestValidator.equals(
    "user ID should remain consistent through atomic update",
    finalUser.id,
    passwordUpdatedUser.id,
  );

  // Step 7: Verify timestamps are properly updated
  TestValidator.predicate(
    "updated_at timestamp should be newer than creation time",
    Date.parse(finalUser.updated_at) >= Date.parse(firstUser.created_at),
  );
  TestValidator.predicate(
    "created_at timestamp should remain unchanged",
    finalUser.created_at === firstUser.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskDescription } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskDescription";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test the complete task status update workflow. A user creates a new user
 * account via the join API to establish authentication, then creates a new task
 * with pending status, and finally updates that task from pending to completed
 * status. This validates that the task status changes correctly, completion
 * timestamp is automatically set when marked as completed, and updated_at field
 * reflects the modification time to track when changes occurred.
 *
 * 1. Create new user account through the join API to establish authentication
 *    credentials
 * 2. Create a new task with pending status to prepare for the status update test
 * 3. Update the task status from pending to completed using the PUT API endpoint
 * 4. Verify the updated task has the correct completed status, completion
 *    timestamp, and updated timestamp
 * 5. Retrieve the task again to confirm all changes persist correctly
 */
export async function test_api_task_update_pending_to_completed(
  connection: api.IConnection,
) {
  // Step 1: Create new user account for authentication
  const email = RandomGenerator.paragraph({ sentences: 2 }) + "@example.com";
  const href = "https://example.com/todo";
  const referrer = "https://example.com/home";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: email satisfies string & tags.Format<"email">,
      password: "password123",
      href: href satisfies string & tags.Format<"uri">,
      referrer: referrer satisfies string & tags.Format<"uri">,
      ip: undefined, // Optional field
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create a new task with pending status
  const taskCreate = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Complete project documentation" satisfies string &
          tags.MinLength<1>,
        description: {
          type: "full" satisfies "full",
          content: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 3,
            sentenceMax: 5,
          }),
        } satisfies ITodoAppTaskDescription.IFull,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskCreate);

  // Verify initial task has pending status
  TestValidator.equals(
    "Task initially has pending status",
    taskCreate.status,
    "pending",
  );
  TestValidator.predicate(
    "Task completed_at is null when pending",
    taskCreate.completed_at === null,
  );

  // Store initial timestamps for comparison
  const originalUpdatedAt = taskCreate.updated_at;
  const originalCreatedAt = taskCreate.created_at;

  // Step 3: Update task status from pending to completed
  const updatedTask = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: taskCreate.id,
      body: {
        status: "completed",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(updatedTask);

  // Step 4: Verify the status update worked correctly
  TestValidator.equals(
    "Task status changed to completed",
    updatedTask.status,
    "completed",
  );
  TestValidator.predicate(
    "Task completed_at is set when completed",
    updatedTask.completed_at !== null,
  );
  TestValidator.predicate(
    "Task completed_at contains valid timestamp",
    updatedTask.completed_at !== undefined,
  );
  TestValidator.notEquals(
    "Updated_at timestamp changed",
    updatedTask.updated_at,
    originalUpdatedAt,
  );
  TestValidator.equals(
    "Created_at timestamp unchanged",
    updatedTask.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "Task ID remains the same",
    updatedTask.id,
    taskCreate.id,
  );
  TestValidator.equals(
    "Task user remains the same",
    updatedTask.user.id,
    taskCreate.user.id,
  );

  // Step 5: Retrieve task again to confirm changes persist
  const retrievedTask = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        status: undefined, // Retrieve all tasks to find our specific one
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(retrievedTask);

  // Find our specific task in the results
  const ourTask = retrievedTask.data.find((task) => task.id === taskCreate.id);
  TestValidator.predicate(
    "Task found in retrieved data",
    ourTask !== undefined,
  );

  if (ourTask) {
    TestValidator.equals(
      "Retrieved task has completed status",
      ourTask.status,
      "completed",
    );
    TestValidator.predicate(
      "Retrieved task has completion timestamp",
      ourTask.completed_at !== null,
    );
  }
}

