import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfiguration";
import { IPageITodoAppConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppConfiguration";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchTodoAppConfigurations(props: {
  body: ITodoAppConfiguration.IRequest;
}): Promise<IPageITodoAppConfiguration.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  const sortBy = props.body.sort_by ?? "key";
  const order = props.body.order ?? "asc";

  // Build dynamic WHERE conditions
  const whereConditions: any = {
    deleted_at: null,
  };

  if (props.body.search) {
    whereConditions.OR = [
      { key: { contains: props.body.search, mode: "insensitive" } },
      { description: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  if (props.body.category) {
    whereConditions.category = props.body.category;
  }

  if (props.body.is_enabled !== undefined) {
    whereConditions.is_enabled = props.body.is_enabled;
  }

  // Validate sort field
  const allowedSortFields = ["key", "category", "created_at", "updated_at"];
  const orderByField = allowedSortFields.includes(sortBy) ? sortBy : "key";

  const [configurations, total] = await Promise.all([
    MyGlobal.prisma.todo_app_configurations.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy: { [orderByField]: order },
      select: {
        id: true,
        key: true,
        value: true,
        description: true,
        is_enabled: true,
      },
    }),
    MyGlobal.prisma.todo_app_configurations.count({
      where: whereConditions,
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: configurations.map((config) => ({
      id: config.id satisfies string as string,
      key: config.key,
      value: config.value,
      description: config.description ?? "",
      is_enabled: config.is_enabled,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppTaskDescription } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskDescription";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoAppUserTasks(props: {
  user: UserPayload;
  body: ITodoAppTask.ICreate;
}): Promise<ITodoAppTask> {
  // Extract description value properly from ITodoAppTaskDescription.IFull type
  const descriptionValue =
    props.body.description?.type === "full"
      ? JSON.stringify(props.body.description.content)
      : typeof props.body.description === "string"
        ? props.body.description
        : props.body.description
          ? JSON.stringify(props.body.description)
          : null;

  // Create the new task with default pending status
  const created = await MyGlobal.prisma.todo_app_tasks.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      title: props.body.title,
      description: descriptionValue satisfies string | null as string | null,
      status: "pending",
      todo_app_user_id: props.user.id,
      created_at: new Date(),
      updated_at: new Date(),
    },
  });

  // Get the user summary for the return
  const user = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.user.id },
  });

  if (!user) {
    throw new HttpException("User not found", 404);
  }

  return {
    id: created.id,
    title: created.title,
    description: created.description ?? undefined,
    status: created.status,
    user: {
      id: user.id,
      email: user.email,
    },
    completed_at: created.completed_at
      ? toISOStringSafe(created.completed_at)
      : undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoAppUser.ILogin;
}): Promise<ITodoAppUser.IAuthorized> {
  // Find user by email
  const user = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Calculate token expiration times as ISO strings
  const now = new Date();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  // Create new session record
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      user_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Generate JWT tokens with ISO timestamps
  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Return authorized user response
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  } satisfies ITodoAppUser.IAuthorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserAuthSessionsSessionId(props: {
  user: UserPayload;
  sessionId: string;
}): Promise<ITodoAppUserSession.IInvert> {
  const session = await MyGlobal.prisma.todo_app_user_sessions.findUnique({
    where: { id: props.sessionId },
    include: {
      user: true,
    },
  });

  if (!session) {
    throw new HttpException("Session not found", 404);
  }

  if (session.user_id !== props.user.id) {
    throw new HttpException("Session does not belong to current user", 403);
  }

  return {
    id: session.id,
    ip: session.ip,
    href: session.href,
    referrer: session.referrer,
    created_at: toISOStringSafe(session.created_at),
    expired_at: session.expired_at
      ? toISOStringSafe(session.expired_at)
      : undefined,
    user_id: session.user_id,
    user: {
      id: session.user.id,
      email: session.user.email,
    },
  };
}

